+        /* COUNT (HFN * snLength^2 + SN) */
+        switch (p_pdcp_nr_info->seqnum_length) {
+            case PDCP_NR_SN_LENGTH_12_BITS:
+                hfn_multiplier = 4096;
+                break;
+            case PDCP_NR_SN_LENGTH_18_BITS:
+                hfn_multiplier = 262144;
+                break;
